window.HOEREN_TESTS[37] = {"id":"babys-und-kleinkinder","name":"Babys und Kleinkinder","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Lisa, hier ist Tante Anna. Ich höre, dein kleiner Max ist schon ein Jahr alt geworden, wie schnell die Zeit vergeht. Ich möchte gerne zu seinem Geburtstag kommen. Wo die Feier ist, weiß ich schon, bei euch zu Hause. Was Max sich wünscht, kannst du mir später sagen. Welcher Tag die Feier ist, das möchte ich wissen: Donnerstag oder Samstag? Ruf mich bitte zurück.","gender":"f","q":"Was möchte Tante Anna wissen?","opts":["Welcher Tag die Feier ist.","Wo die Feier ist.","Was Max sich wünscht."],"correct":0},{"transcript":"Liebe Eltern, der Kindergarten Sonnenstrahl bleibt nächsten Montag geschlossen. Wir haben Personal-Fortbildung, es ist kein normaler Betrieb und auch keine Eltern-Versammlung. Kinder sollten bitte zu Hause bleiben oder mit anderen Eltern eine Lösung finden. Dienstag ist wieder normaler Betrieb, vielen Dank für Ihr Verständnis.","gender":"f","q":"Was passiert am Montag?","opts":["Normaler Betrieb.","Kindergarten geschlossen.","Eltern-Versammlung."],"correct":1},{"transcript":"Hi Markus, hier ist Sara. Pass auf, ich brauche dringend einen Tipp. Mein Baby Emma schreit nachts immer um 3 Uhr, ich bin total müde. Das Baby isst nicht schlecht, und krank ist sie auch nicht. Das Problem ist: Das Baby schreit nachts. Deine Tochter hat das ja auch gemacht. Was hilft? Vielleicht Tee, vielleicht Musik? Ruf mich an.","gender":"f","q":"Was ist das Problem?","opts":["Das Baby isst nicht.","Das Baby ist krank.","Das Baby schreit nachts."],"correct":2},{"transcript":"Achtung Eltern: Im Babyladen MiniMax gibt es ab heute Sonderangebot! Babywindeln 30 Prozent billiger, Babynahrung 20 Prozent billiger, Spielzeug 50 Prozent billiger. Spielzeug ist also am billigsten im Angebot. Nur diese Woche, also bis Samstag. Wir freuen uns auf euren Besuch im Stadtzentrum am Marktplatz, kommt gerne vorbei.","gender":"m","q":"Was ist am billigsten?","opts":["Babywindeln.","Babynahrung.","Spielzeug."],"correct":2},{"transcript":"Hallo Doktor, hier ist Familie Bauer. Unser Kind Tim hat hohes Fieber, 39 Grad, schon seit zwei Tagen. Er hustet fast nicht, und er isst noch ein bisschen. Das Problem ist das hohe Fieber. Wir möchten gerne einen Termin heute, möglichst bald. Bitte rufen Sie zurück.","gender":"f","q":"Was ist das Problem?","opts":["Tim hat hohes Fieber.","Tim hustet.","Tim isst nicht."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Welches Kind liebt was? Wählen Sie für jedes Kind einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Im Kinderzimmer liegt heute alles durcheinander."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Jedes Kind hat ein Lieblingsspielzeug. Danach räumen wir die Kisten."},{"speaker":"Lukas","gender":"m","text":"Ich spiele am liebsten mit Autos. Die kleinen Wagen stehen unter dem Bett."},{"speaker":"Lisa","gender":"f","text":"Du fährst sie oft bis in die Küche. Das kenne ich schon."},{"speaker":"Lukas","gender":"m","text":"Mag noch jemand von den Kindern Bauklötze?"},{"speaker":"Lisa","gender":"f","text":"Nein. Bauklötze mag keiner mehr."},{"speaker":"Lukas","gender":"m","text":"Deine Ecke ist voll mit kleinen Kleidern aus Stoff."},{"speaker":"Lisa","gender":"f","text":"Puppen mag ich am meisten. Die rote bleibt immer bei mir."},{"speaker":"Lukas","gender":"m","text":"Tom brüllt morgens oft wie ein Tier aus der Urzeit."},{"speaker":"Lisa","gender":"f","text":"Tom liebt Dinosaurier. Der grüne steht oben auf dem Regal."},{"speaker":"Lukas","gender":"m","text":"Sara drückt abends immer etwas Weiches fest an sich."},{"speaker":"Lisa","gender":"f","text":"Sara liebt Plüschtiere. Ohne den Bären schläft sie nicht."},{"speaker":"Lukas","gender":"m","text":"Wollen die Kinder auch Bälle?"},{"speaker":"Lisa","gender":"f","text":"Nein. Bälle wollen sie auch nicht."},{"speaker":"Lukas","gender":"m","text":"Tim sitzt still in der Ecke und blättert Seiten um."},{"speaker":"Lisa","gender":"f","text":"Tim liebt Bücher. Jeden Abend hört er eine Geschichte."},{"speaker":"Lukas","gender":"m","text":"Dann stellen wir die Kisten nach den Namen hin."},{"speaker":"Lisa","gender":"f","text":"Ich schreibe Zettel und klebe sie auf die Deckel."}],"options":[{"letter":"a","text":"Bauklötze"},{"letter":"b","text":"Bälle"},{"letter":"c","text":"Plüschtiere"},{"letter":"d","text":"Puppen"},{"letter":"e","text":"Dinosaurier"},{"letter":"f","text":"Bücher"},{"letter":"g","text":"Malen"},{"letter":"h","text":"Musik"},{"letter":"i","text":"Autos"}],"items":[{"person":"Lukas","correct":"i"},{"person":"Lisa","correct":"d"},{"person":"Tom","correct":"e"},{"person":"Sara","correct":"c"},{"person":"Tim","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mutter","gender":"f","text":"Wann sollen wir Emma impfen lassen? Mit 5 Monaten, mit 6 Monaten oder erst mit 12 Monaten?"},{"speaker":"Ärztin","gender":"f","text":"Mit 6 Monaten ist die erste Impfung. Dann mit 12 und 18 Monaten, mit 5 Monaten ist es noch früh."},{"speaker":"Mutter","gender":"f","text":"Sie ist jetzt 5 Monate, also nicht heute mit 5, und nicht warten bis 12?"},{"speaker":"Ärztin","gender":"f","text":"Genau, nächsten Monat mit 6 Monaten. Mit 12 Monaten kommt die nächste Impfung, nicht die erste."},{"speaker":"Mutter","gender":"f","text":"Gut, dann geben Sie uns bitte einen Termin für nächsten Monat."}],"q":"Wann ist die erste Impfung?","opts":["Mit 5 Monaten.","Mit 12 Monaten.","Mit 6 Monaten."],"correct":2},{"lines":[{"speaker":"Verkäufer","gender":"m","text":"Welche Babynahrung suchen Sie? Gemüse-Brei, Obst-Brei oder Milchbrei?"},{"speaker":"Mutter","gender":"f","text":"Was ist gut für ein 8 Monate altes Baby? Ich bin unsicher."},{"speaker":"Verkäufer","gender":"m","text":"Gemüse-Brei oder Obst-Brei. Auch Milchbrei mit Getreide geht, aber später am Abend."},{"speaker":"Mutter","gender":"f","text":"Obst-Brei nimmt sie nicht, und Milchbrei mag sie auch nicht. Dann Gemüse-Brei."},{"speaker":"Verkäufer","gender":"m","text":"Gut, drei Gläser Gemüse-Brei. Das reicht für ein paar Tage."}],"q":"Was kauft die Mutter?","opts":["Obst-Brei.","Gemüse-Brei.","Milchbrei."],"correct":1},{"lines":[{"speaker":"Vater","gender":"m","text":"Frau Schmidt, ist Klein-Max gut im Kindergarten? Isst er Frühstück, Mittagessen und Abendessen?"},{"speaker":"Erzieherin","gender":"f","text":"Sehr gut, er spielt schön mit anderen Kindern. Abendessen gibt es bei uns nicht, nur bis nachmittags."},{"speaker":"Vater","gender":"m","text":"Isst er auch? Frühstück und Mittagessen?"},{"speaker":"Erzieherin","gender":"f","text":"Mittagessen ja, aber das Frühstück ignoriert er meistens. Abendessen macht ihr zu Hause."},{"speaker":"Vater","gender":"m","text":"Verstehe, bei uns dann mehr Frühstück am Morgen. Danke für den Hinweis."}],"q":"Was isst Max nicht?","opts":["Frühstück.","Mittagessen.","Abendessen."],"correct":0},{"lines":[{"speaker":"Mutter","gender":"f","text":"Tim, was möchtest du zum Geburtstag? Ein Fahrrad, ein Laufrad, oder nichts, nur eine Feier?"},{"speaker":"Tim","gender":"m","text":"Ein Fahrrad! Bitte, Mama, ein richtiges Fahrrad."},{"speaker":"Mutter","gender":"f","text":"Du bist erst 4, etwas klein für ein Fahrrad. Nichts ist unfair, ein Laufrad vielleicht?"},{"speaker":"Tim","gender":"m","text":"Okay, dann Laufrad, wenn ich 6 bin, dann ein richtiges Fahrrad. Leer ausgehen will ich nicht."},{"speaker":"Mutter","gender":"f","text":"Gut, dann ein Laufrad, wir schauen am Samstag im Laden."}],"q":"Was bekommt Tim?","opts":["Ein Fahrrad.","Ein Laufrad.","Nichts."],"correct":1},{"lines":[{"speaker":"Mutter1","gender":"f","text":"Wie schläft dein Baby? Bei uns helfen Tee und Spaziergänge nicht so richtig."},{"speaker":"Mutter2","gender":"f","text":"Anfangs schlimm, aber jetzt 8 Stunden durchgehend, ohne Tee."},{"speaker":"Mutter1","gender":"f","text":"Wow, Glück gehabt! Mein Sohn schläft nur 4 Stunden, dann wach. Spaziergänge machen wir schon."},{"speaker":"Mutter2","gender":"f","text":"Vielleicht Hunger? Mehr Abendmilch hilft, tee und nur Spaziergänge waren bei uns zu wenig."},{"speaker":"Mutter1","gender":"f","text":"Dann probiere ich mehr Abendmilch. Danke für den Tipp."}],"q":"Was empfiehlt die zweite Mutter?","opts":["Mehr Abendmilch.","Tee.","Spaziergänge."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Walter, einer Kinderärztin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Doktor Walter, Sie arbeiten als Kinderärztin seit 20 Jahren. Was hat sich in dieser Zeit verändert?"},{"speaker":"Walter","gender":"f","text":"Vieles. Vor 20 Jahren waren Eltern entspannter — heute sind sie sehr nervös. Sie googeln alle Symptome, kommen mit ‚Diagnose‘ in die Praxis. Manchmal hilfreich, oft falsch. Geduldig erklären gehört jetzt zum Beruf."},{"speaker":"Reporter","gender":"m","text":"Welche Probleme sehen Sie am häufigsten?"},{"speaker":"Walter","gender":"f","text":"Erkältungen klar, das hat sich nicht geändert. Aber Übergewicht ist neu — viele Kinder bewegen sich zu wenig, essen zu viel Süßes. Und Schlafprobleme — die Kleinen schauen zu viel auf Bildschirme vor dem Schlafen."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie Eltern?"},{"speaker":"Walter","gender":"f","text":"Bewegung jeden Tag, mindestens eine Stunde draußen. Kein Bildschirm eine Stunde vor dem Schlafen. Süßes nicht verbieten, aber begrenzen — vielleicht nur am Wochenende. Und: ruhig bleiben, nicht jedes kleine Husten zur Krise machen."},{"speaker":"Reporter","gender":"m","text":"Sind Impfungen heute ein Thema?"},{"speaker":"Walter","gender":"f","text":"Leider ja, manche Eltern sind skeptisch. Ich erkläre dann ruhig die Wissenschaft. Die meisten lassen impfen nach dem Gespräch — Vertrauen ist wichtig."},{"speaker":"Reporter","gender":"m","text":"Haben Sie eigene Kinder?"},{"speaker":"Walter","gender":"f","text":"Drei. Die ältesten zwei studieren schon, die Jüngste ist 16. Als Kinderärztin war ich vielleicht zu streng, aber sie sind gesund."}],"items":[{"q":"Übergewicht ist ein neues Problem bei Kindern.","correct":"ja"},{"q":"Eltern sind heute entspannter als früher.","correct":"nein"},{"q":"Sie rät, Süßes komplett zu verbieten.","correct":"nein"},{"q":"Sie erklärt skeptischen Eltern die Impfungen ruhig.","correct":"ja"},{"q":"Sie hat selbst keine Kinder.","correct":"nein"}]}]};
